// src/utils/feeFilter.js
export const filterFeesByClass = (items, studentClass) => {
  const cls = Number(studentClass);
  const filtered = { ...items };

  if (cls >= 1 && cls <= 5) {
    ["labs", "sports", "artMusic", "dance", "art"].forEach(k => delete filtered[k]);
  } else if (cls >= 6 && cls <= 9) {
    delete filtered["exam"];
  }
  // For 10–12 → show all
  return filtered;
};
